import json,boto3,urllib.request
def cfn_send(url,body):
    req=urllib.request.Request(url,data=json.dumps(body).encode(),method='PUT',headers={'Content-Type':''})
    urllib.request.urlopen(req)
def handler(event,context):
    rt=event['RequestType']
    name=event['ResourceProperties'].get('LedgerName','vote-capsule-trust')
    base={'StackId':event['StackId'],'RequestId':event['RequestId'],'LogicalResourceId':event['LogicalResourceId']}
    try:
        cl=boto3.client('qldb')
        if rt=='Create':
            try: r=cl.create_ledger(Name=name,PermissionsMode='STANDARD',DeletionProtection=False)
            except: r=cl.describe_ledger(Name=name)
            cfn_send(event['ResponseURL'],{**base,'Status':'SUCCESS','PhysicalResourceId':r['Arn'],'Data':{'LedgerName':name,'State':r['State']}})
        elif rt=='Delete':
            try: cl.delete_ledger(Name=name)
            except: pass
            cfn_send(event['ResponseURL'],{**base,'Status':'SUCCESS','PhysicalResourceId':event.get('PhysicalResourceId',name),'Data':{}})
        else:
            r=cl.describe_ledger(Name=name)
            cfn_send(event['ResponseURL'],{**base,'Status':'SUCCESS','PhysicalResourceId':event['PhysicalResourceId'],'Data':{'State':r['State']}})
    except Exception as e:
        cfn_send(event['ResponseURL'],{**base,'Status':'SUCCESS','PhysicalResourceId':name,'Data':{'Note':'QLDB unavailable','Error':str(e)[:200]}})
